/*
 * A059666  Primes p such that x^54 = 2 has no solution mod p, but x^18 = 2
 *          has a solution mod p.
 * https://oeis.org/A059666
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 18, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A059666 – Primes p such that x^54 ≡ 2 (mod p) has no solution but x^18 ≡ 2 (mod p) does.
 *
 *  The sequence is generated by enumerating primes in increasing order that
 *  satisfy p ≡ 1 (mod 54).  For each such prime p the two conditions are
 *  checked using modular exponentiation:
 *
 *      2^((p-1)/18) ≡ 1 (mod p)    (there is a solution to x^18 ≡ 2)
 *      2^((p-1)/54) ≠ 1 (mod p)    (no solution to x^54 ≡ 2)
 *
 *  The list of terms is cached so that random calls to a(idx_t) are fast.
 *  All arithmetic inside the test is performed with uint64_t, which is
 *  sufficient for the values needed up to at least n = 10 000.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

/* ------------------------------------------------------------- */
/*  Helper functions for modular arithmetic (uint64_t)          */
/* ------------------------------------------------------------- */

static inline uint64_t mod_mul(uint64_t a, uint64_t b, uint64_t mod)
{
    return (uint64_t)((__uint128_t)a * b % mod);
}

static uint64_t mod_pow(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t res = 1;
    while (exp) {
        if (exp & 1)
            res = mod_mul(res, base, mod);
        base = mod_mul(base, base, mod);
        exp >>= 1;
    }
    return res;
}

/* Deterministic Miller–Rabin primality test for 64‑bit integers.
 * Bases {2,3,5,7,11,13,17} are sufficient for n < 2^64. */
static bool is_prime_uint64(uint64_t n)
{
    if (n < 2)
        return false;
    /* Check divisibility by small primes first */
    static const uint64_t small_primes[] = {2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL};
    for (size_t i = 0; i < sizeof(small_primes)/sizeof(small_primes[0]); ++i) {
        uint64_t p = small_primes[i];
        if (n == p)
            return true;
        if (n % p == 0)
            return false;
    }

    /* Write n‑1 as d·2^s with d odd */
    uint64_t d = n - 1;
    uint64_t s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    /* Test with the same witnesses as above */
    for (size_t i = 0; i < sizeof(small_primes)/sizeof(small_primes[0]); ++i) {
        uint64_t a = small_primes[i];
        if (a >= n)
            continue;
        uint64_t x = mod_pow(a, d, n);
        if (x == 1 || x == n - 1)
            continue;
        bool composite = true;
        for (uint64_t r = 1; r < s; ++r) {
            x = mod_mul(x, x, n);
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;
}

/* ------------------------------------------------------------- */
/*  Storage of found terms                                      */
/* ------------------------------------------------------------- */

static uint64_t *prime_terms = NULL;   /* array of prime values (uint64_t) */
static size_t   prime_len   = 0;       /* number of stored terms */
static size_t   prime_cap   = 0;       /* allocated capacity      */
static uint64_t candidate   = 55;      /* next prime candidate ≡ 1 (mod 54) */

/* Append a new prime term, resizing if necessary */
static void add_prime(uint64_t p)
{
    if (prime_len == prime_cap) {
        size_t new_cap = (prime_cap == 0) ? 8 : prime_cap * 2;
        uint64_t *tmp = (uint64_t *)realloc(prime_terms, new_cap * sizeof(uint64_t));
        if (!tmp) abort();          /* allocation failure */
        prime_terms = tmp;
        prime_cap   = new_cap;
    }
    prime_terms[prime_len++] = p;
}

/* ------------------------------------------------------------- */
/*  Main sequence function                                       */
/* ------------------------------------------------------------- */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;  /* undefined for n = 0, return 0 as dummy */

    /* Grow cache until we have at least n terms. */
    while (prime_len < (size_t)n) {
        /* Find the next prime that satisfies the two conditions. */
        while (true) {
            uint64_t p = candidate;
            candidate += 54;          /* next candidate ≡ 1 (mod 54) */

            if (!is_prime_uint64(p))
                continue;            /* not prime */

            /* Check solvability conditions. */
            uint64_t r54 = mod_pow(2ULL, (p - 1) / 54, p);
            if (r54 == 1ULL)
                continue;            /* 2 is a 54th power – reject */

            uint64_t r18 = mod_pow(2ULL, (p - 1) / 18, p);
            if (r18 != 1ULL)
                continue;            /* 2 is not an 18th power – reject */

            /* Satisfies both conditions – store it. */
            add_prime(p);
            break;
        }
    }

    /* Return the nth term (indexing starts at 1). */
    return (seq_t)prime_terms[n - 1];
}
